const quiet=new Set(['LINDA OBADIA','AMANDA SOUSA','KEVIN WONG','Arunn Arora','GURMEET GURM','SCOTT WILLIAM DUVALL','MUHAMMAD USMAN','MARIA JUDAS','Happy Wednesday','MOKSHI VIRK']);
for(const r of rows.filter(r=>quiet.has(r.contact.name))){for(const t of r.thread.filter(t=>t.direction==='inbound'&&t.created_at>'2026-10-10T22:00:00Z')){const reason=r.contact.name==='Happy Wednesday'?'Automated leasing follow-up, not a Saturn moving enquiry.':r.contact.name==='MOKSHI VIRK'?'Call intention captured in John task; digital card already sent.':'Acknowledgement/reaction or future interest; no additional question, card request or live moving job. Preserve any existing commitments.';await reviewed(t.id,reason,{});const [current]=await db('market_touches',{id:'eq.'+t.id});await db('market_touches',{id:'eq.'+t.id},'PATCH',{metadata:{...current.metadata,partnership_ai:{...current.metadata?.partnership_ai,intent:r.contact.name==='Happy Wednesday'?'automated_reply':'warm_acknowledgement',draft_sms:'',recommended_action:'no_reply',rationale:reason}},next_step:'Reviewed: no additional SMS required.'});result.reviews.push(t.id);}}
